-- Generated from current ItemList.bin + Item_Str.xml on 2026-06-08.
-- Covers XML-resolved missing containers and supported chipset scan patterns.
BEGIN;

CREATE TEMP TABLE _lk_xml_container (item_id int primary key, item_name text not null, reward_amount int not null, source text not null) ON COMMIT DROP;
CREATE TEMP TABLE _lk_xml_container_reward (container_item_id int not null, reward_item_id int not null, reward_item_name text not null, min_amount int not null, max_amount int not null, chance numeric(9,2) not null, rare boolean not null) ON COMMIT DROP;
CREATE TEMP TABLE _lk_xml_scan (item_id int primary key, item_name text not null, min_amount smallint not null, max_amount smallint not null, source text not null) ON COMMIT DROP;
CREATE TEMP TABLE _lk_xml_scan_reward (scan_item_id int not null, reward_item_id int not null, reward_item_name text not null, min_amount int not null, max_amount int not null, chance numeric(9,2) not null, rare boolean not null) ON COMMIT DROP;

