DO $$
DECLARE
    rec record;
    target_id bigint;
BEGIN
    FOR rec IN SELECT * FROM _lk_xml_container ORDER BY item_id LOOP
        SELECT "Id" INTO target_id
        FROM dso."Asset_Container"
        WHERE "ItemId" = rec.item_id
        ORDER BY "Id"
        LIMIT 1;

        IF target_id IS NULL THEN
            INSERT INTO dso."Asset_Container" ("ItemId", "ItemName", "RewardAmount")
            VALUES (rec.item_id, rec.item_name, rec.reward_amount)
            RETURNING "Id" INTO target_id;
        ELSE
            UPDATE dso."Asset_Container"
            SET "ItemName" = rec.item_name,
                "RewardAmount" = rec.reward_amount
            WHERE "Id" = target_id;

            DELETE FROM dso."Asset_ContainerReward"
            WHERE "ContainerAssetId" = target_id;
        END IF;

        INSERT INTO dso."Asset_ContainerReward"
            ("ItemId", "ItemName", "MinAmount", "MaxAmount", "Chance", "Rare", "ContainerAssetId")
        SELECT reward_item_id, reward_item_name, min_amount, max_amount, chance, rare, target_id
        FROM _lk_xml_container_reward
        WHERE container_item_id = rec.item_id
        ORDER BY reward_item_id;
    END LOOP;

    FOR rec IN SELECT * FROM _lk_xml_scan ORDER BY item_id LOOP
        SELECT "Id" INTO target_id
        FROM dso."Asset_ScanDetail"
        WHERE "ItemId" = rec.item_id
        ORDER BY "Id"
        LIMIT 1;

        IF target_id IS NULL THEN
            INSERT INTO dso."Asset_ScanDetail" ("MinAmount", "MaxAmount", "ItemId", "ItemName")
            VALUES (rec.min_amount, rec.max_amount, rec.item_id, rec.item_name)
            RETURNING "Id" INTO target_id;
        ELSE
            UPDATE dso."Asset_ScanDetail"
            SET "MinAmount" = rec.min_amount,
                "MaxAmount" = rec.max_amount,
                "ItemName" = rec.item_name
            WHERE "Id" = target_id;

            DELETE FROM dso."Asset_ScanRewardDetail"
            WHERE "ScanDetailAssetId" = target_id;
        END IF;

        INSERT INTO dso."Asset_ScanRewardDetail"
            ("ItemId", "ItemName", "MinAmount", "MaxAmount", "Chance", "Rare", "ScanDetailAssetId")
        SELECT reward_item_id, reward_item_name, min_amount, max_amount, chance, rare, target_id
        FROM _lk_xml_scan_reward
        WHERE scan_item_id = rec.item_id
        ORDER BY reward_item_id;
    END LOOP;
END $$;

COMMIT;
